/// Remove consecutive duplicate vertices (including the wrap-around pair),
/// mirroring Clipper2's habit of not emitting duplicate points.
fn dedup(path: Path64) -> Path64 {
    let mut out: Path64 = Path64::with_capacity(path.len());
    for pt in path {
        if out.last() != Some(&pt) {
            out.push(pt);
        }
    }
    while out.len() > 1 && out.first() == out.last() {
        out.pop();
    }
    out
}
